203	      const threshold = this.config.getTruncateToolOutputThreshold();
204	
205	      if (threshold > 0 && content.length > threshold) {
206	        const originalContentLength = content.length;
207	        const { outputFile: savedPath } = await saveTruncatedToolOutput(
208	          content,
209	          toolName,
210	          callId,
211	          this.config.storage.getProjectTempDir(),
212	          this.context.promptId,
213	        );
214	        outputFile = savedPath;
215	        const truncatedContent = formatTruncatedToolOutput(
216	          content,
217	          outputFile,
218	          threshold,
219	        );
220	
221	        logToolOutputTruncated(
222	          this.config,
223	          new ToolOutputTruncatedEvent(call.request.prompt_id, {
224	            toolName,
225	            originalContentLength,
226	            truncatedContentLength: truncatedContent.length,
227	            threshold,
228	          }),
229	        );
230	
231	        return { truncatedContent, outputFile };
