17	 * Options for scheduling agent tools.
18	 */
19	export interface AgentSchedulingOptions {
20	  /** The unique ID for this agent's scheduler. */
21	  schedulerId: string;
22	  /** The ID of the tool call that invoked this agent. */
23	  parentCallId?: string;
24	  /** The tool registry specific to this agent. */
25	  toolRegistry: ToolRegistry;
26	  /** AbortSignal for cancellation. */
27	  signal: AbortSignal;
28	  /** Optional function to get the preferred editor for tool modifications. */
29	  getPreferredEditor?: () => EditorType | undefined;
30	  /** Optional function to be notified when the scheduler is waiting for user confirmation. */
31	  onWaitingForConfirmation?: (waiting: boolean) => void;
32	}
