107	
108	  constructor(private readonly config: Config) {
109	    this.loopDetector = new LoopDetectionService(config);
110	    this.compressionService = new ChatCompressionService();
111	    this.toolOutputMaskingService = new ToolOutputMaskingService();
112	    this.lastPromptId = this.config.getSessionId();
113	
114	    coreEvents.on(CoreEvent.ModelChanged, this.handleModelChanged);
115	  }
116	
117	  private handleModelChanged = () => {
118	    this.currentSequenceModel = null;
119	  };
