121	  // Hook state to deduplicate BeforeAgent calls and track response for
122	  // AfterAgent
123	  private hookStateMap = new Map<
124	    string,
125	    {
126	      hasFiredBeforeAgent: boolean;
127	      cumulativeResponse: string;
128	      activeCalls: number;
129	      originalRequest: PartListUnion;
130	    }
131	  >();
132	
133	  private async fireBeforeAgentHookSafe(
134	    request: PartListUnion,
135	    prompt_id: string,
136	  ): Promise<BeforeAgentHookReturn> {
137	    let hookState = this.hookStateMap.get(prompt_id);
138	    if (!hookState) {
139	      hookState = {
140	        hasFiredBeforeAgent: false,
141	        cumulativeResponse: '',
142	        activeCalls: 0,
143	        originalRequest: request,
144	      };
145	      this.hookStateMap.set(prompt_id, hookState);
146	    }
147	
148	    // Increment active calls for this prompt_id
149	    // This is called at the start of sendMessageStream, so it acts as an entry
150	    // counter. We increment here, assuming this helper is ALWAYS called at
151	    // entry.
152	    hookState.activeCalls++;
153	
154	    if (hookState.hasFiredBeforeAgent) {
155	      return undefined;
156	    }
157	
158	    const hookOutput = await this.config
159	      .getHookSystem()
160	      ?.fireBeforeAgentEvent(partToString(request));
161	    hookState.hasFiredBeforeAgent = true;
162	
163	    if (hookOutput?.shouldStopExecution()) {
164	      return {
165	        type: GeminiEventType.AgentExecutionStopped,
166	        value: {
167	          reason: hookOutput.getEffectiveReason(),
168	          systemMessage: hookOutput.systemMessage,
169	        },
170	      };
171	    }
172	
173	    if (hookOutput?.isBlockingDecision()) {
174	      return {
175	        type: GeminiEventType.AgentExecutionBlocked,
176	        value: {
177	          reason: hookOutput.getEffectiveReason(),
178	          systemMessage: hookOutput.systemMessage,
179	        },
180	      };
181	    }
182	
183	    const additionalContext = hookOutput?.getAdditionalContext();
184	    if (additionalContext) {
185	      return { additionalContext };
186	    }
187	    return undefined;
188	  }
189	
190	  private async fireAfterAgentHookSafe(
191	    currentRequest: PartListUnion,
192	    prompt_id: string,
193	    turn?: Turn,
194	    stopHookActive: boolean = false,
195	  ): Promise<DefaultHookOutput | undefined> {
196	    const hookState = this.hookStateMap.get(prompt_id);
197	    // Only fire on the outermost call (when activeCalls is 1)
198	    if (!hookState || (hookState.activeCalls !== 1 && !stopHookActive)) {
199	      return undefined;
200	    }
201	
202	    if (turn && turn.pendingToolCalls.length > 0) {
203	      return undefined;
204	    }
205	
206	    const finalResponseText =
207	      hookState.cumulativeResponse ||
208	      turn?.getResponseText() ||
209	      '[no response text]';
210	    const finalRequest = hookState.originalRequest || currentRequest;
211	
212	    const hookOutput = await this.config
213	      .getHookSystem()
214	      ?.fireAfterAgentEvent(
215	        partToString(finalRequest),
216	        finalResponseText,
217	        stopHookActive,
